export const SKILLS={stamina:'Stamina',acceleration:'Acceleration',velocity:'Velocity',power:'Hit power',accuracy:'Hit accuracy',consistency:'Unforced errors',intelligence:'Intelligence'};
const names=['Whitney','Graham','Charles','Prescott','Brooks','Spencer','Harrison','Winston','Bradford','Montgomery','Bennett','Alistair','Étienne','Lucien','Henri','Philippe','Olivier','François','Laurent','Gaston','Thibault','Armand','Jacques','Rémy'];
const ids=['whitney','graham','charles','prescott','brooks','spencer','harrison','winston','bradford','montgomery','bennett','alistair','etienne','lucien','henri','philippe','olivier','francois','laurent','gaston','thibault','armand','jacques','remy'];
const bases=[83,45,68,91,34,76,55,24,62,86,40,71,95,31,81,50,66,38,88,57,22,73,47,60];let seed=194718;const random=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};
export const ROSTER=names.map((name,i)=>{const ratings=Object.fromEntries(Object.keys(SKILLS).map(k=>[k,Math.max(1,Math.min(100,Math.round(bases[i]+random()*34-17)))]));return Object.freeze({id:ids[i],name,ratings:Object.freeze(ratings),average:Math.round(Object.values(ratings).reduce((a,b)=>a+b,0)/7),height:66+(i*5)%13,weight:160+(i*13)%41,skin:['#d9b294','#c69673','#ab7755','#dfbfa6','#966c50','#c5a58c'][i%6],hair:['#39322d','#805237','#c6af70','#77736d','#372b23','#a56c44'][i%6],band:['#cf4940','#448bb5','#61a18b','#d5b655','#9a6ba5','#eee9d8'][i%6],wrist:['#52988c','#bd5d4e','#c2ab62','#517ca8','#ad84a6','#ece5d4'][(i*5)%6],hat:i===3||i===17,hatColor:i===3?'#e8e4d8':'#526874'});});
export function getCharacter(id,fallback='whitney'){return ROSTER.find(p=>p.id===id)??ROSTER.find(p=>p.id===fallback)??ROSTER[0];}
export const buildLabel=c=>`${Math.floor(c.height/12)}′${c.height%12}″ · ${c.weight} lb`;
export const bodyScale=c=>({height:c.height/72,width:Math.sqrt((c.weight/180)/(c.height/72))});
